def climbStairs(n):
    if n <= 2: return n
    a, b = 1, 2
    for _ in range(3, n+1):
        a, b = b, a+b
    return b

def fib(n):
    if n <= 1: return n
    a, b = 0, 1
    for _ in range(2, n+1):
        a, b = b, a+b
    return b

def rob(nums):
    prev2, prev1 = 0, 0
    for n in nums:
        prev2, prev1 = prev1, max(prev1, prev2 + n)
    return prev1

def minCostClimbingStairs(cost):
    n = len(cost)
    a, b = cost[0], cost[1]
    for i in range(2, n):
        a, b = b, cost[i] + min(a, b)
    return min(a, b)

def generate(numRows):
    triangle = []
    for r in range(numRows):
        row = [1] * (r+1)
        for j in range(1, r):
            row[j] = triangle[r-1][j-1] + triangle[r-1][j]
        triangle.append(row)
    return triangle

def getRow(rowIndex):
    row = [1] * (rowIndex+1)
    for i in range(1, rowIndex+1):
        for j in range(i-1, 0, -1):
            row[j] += row[j-1]
    return row

def maxSubArray(nums):
    curr = best = nums[0]
    for n in nums[1:]:
        curr = max(n, curr + n)
        best = max(best, curr)
    return best

class NumArray:
    def __init__(self, nums):
        self.prefix = [0] * (len(nums)+1)
        for i, n in enumerate(nums):
            self.prefix[i+1] = self.prefix[i] + n
    def sumRange(self, left, right):
        return self.prefix[right+1] - self.prefix[left]

na = NumArray([-2,0,3,-5,2,-1])

def countBits(n):
    dp = [0] * (n+1)
    for i in range(1, n+1):
        dp[i] = dp[i >> 1] + (i & 1)
    return dp

def isSubsequence(s, t):
    i = 0
    for c in t:
        if i < len(s) and c == s[i]:
            i += 1
    return i == len(s)

def getMaximumGenerated(n):
    if n == 0: return 0
    nums = [0] * (n+1)
    nums[1] = 1
    for i in range(1, n//2 + 1):
        nums[2*i] = nums[i]
        if 2*i+1 <= n:
            nums[2*i+1] = nums[i] + nums[i+1]
    return max(nums)

def maxTurbulenceSize(arr):
    n = len(arr)
    if n < 2: return n
    inc = dec = 1  # ending with up / down move
    best = 1
    for i in range(1, n):
        if arr[i] > arr[i-1]:
            inc = dec + 1; dec = 1
        elif arr[i] < arr[i-1]:
            dec = inc + 1; inc = 1
        else:
            inc = dec = 1
        best = max(best, inc, dec)
    return best

def canJump(nums):
    max_reach = 0
    for i, n in enumerate(nums):
        if i > max_reach: return False
        max_reach = max(max_reach, i + n)
    return True

def hammingWeight(n):
    count = 0
    while n:
        n &= (n-1)
        count += 1
    return count

def reverseBits(n):
    result = 0
    for _ in range(32):
        result = (result << 1) | (n & 1)
        n >>= 1
    return result

def uniquePaths(m, n):
    dp = [1] * n
    for _ in range(1, m):
        for c in range(1, n):
            dp[c] += dp[c-1]
    return dp[-1]

def coinChange(coins, amount):
    dp = [float("inf")] * (amount+1)
    dp[0] = 0
    for coin in coins:
        for i in range(coin, amount+1):
            dp[i] = min(dp[i], dp[i-coin]+1)
    return dp[amount] if dp[amount] != float("inf") else -1

import bisect

def lengthOfLIS(nums):
    tails = []  # tails[i] = smallest tail of IS of length i+1
    for n in nums:
        pos = bisect.bisect_left(tails, n)
        if pos == len(tails): tails.append(n)
        else: tails[pos] = n
    return len(tails)

def robII(nums):
    def rob_range(arr):
        prev2, prev1 = 0, 0
        for n in arr:
            prev2, prev1 = prev1, max(prev1, prev2+n)
        return prev1
    if len(nums) == 1: return nums[0]
    return max(rob_range(nums[:-1]), rob_range(nums[1:]))

def canPartition(nums):
    total = sum(nums)
    if total % 2: return False
    target = total // 2
    dp = {0}
    for n in nums:
        dp = dp | {s+n for s in dp if s+n <= target}
    return target in dp

def jump(nums):
    jumps = cur_end = farthest = 0
    for i in range(len(nums)-1):
        farthest = max(farthest, i + nums[i])
        if i == cur_end:
            jumps += 1
            cur_end = farthest
    return jumps

def numDecodings(s):
    if not s or s[0] == '0': return 0
    prev2, prev1 = 1, 1
    for i in range(1, len(s)):
        curr = 0
        if s[i] != '0':
            curr += prev1
        two = int(s[i-1:i+1])
        if 10 <= two <= 26:
            curr += prev2
        prev2, prev1 = prev1, curr
    return prev1

def wordBreak(s, wordDict):
    word_set = set(wordDict)
    n = len(s)
    dp = [False] * (n+1)
    dp[0] = True
    for i in range(1, n+1):
        for j in range(i):
            if dp[j] and s[j:i] in word_set:
                dp[i] = True; break
    return dp[n]

def longestPalindrome(s):
    def expand(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1; r += 1
        return s[l+1:r]
    result = ""
    for i in range(len(s)):
        for sub in [expand(i,i), expand(i,i+1)]:
            if len(sub) > len(result): result = sub
    return result

def minPathSum(grid):
    m, n = len(grid), len(grid[0])
    dp = grid[0][:]
    for c in range(1, n): dp[c] += dp[c-1]  # first row
    for r in range(1, m):
        dp[0] += grid[r][0]
        for c in range(1, n):
            dp[c] = grid[r][c] + min(dp[c], dp[c-1])
    return dp[-1]

def findTargetSumWaysDP(nums, target):
    total = sum(nums)
    if (total + target) % 2 != 0 or abs(target) > total: return 0
    t = (total + target) // 2
    dp = [0] * (t+1)
    dp[0] = 1
    for n in nums:
        for j in range(t, n-1, -1):
            dp[j] += dp[j-n]
    return dp[t]

def findLength(nums1, nums2):
    m, n = len(nums1), len(nums2)
    dp = [0] * (n+1)
    result = 0
    for i in range(1, m+1):
        new_dp = [0] * (n+1)
        for j in range(1, n+1):
            if nums1[i-1] == nums2[j-1]:
                new_dp[j] = dp[j-1] + 1
                result = max(result, new_dp[j])
        dp = new_dp
    return result

def countTextsFull(pressedKeys):
    MOD = 10**9 + 7
    n = len(pressedKeys)
    dp = [0] * (n+1)
    dp[0] = 1
    for i in range(1, n+1):
        dp[i] = dp[i-1]
        if i >= 2 and pressedKeys[i-1] == pressedKeys[i-2]:
            dp[i] = (dp[i] + dp[i-2]) % MOD
            if i >= 3 and pressedKeys[i-1] == pressedKeys[i-3]:
                dp[i] = (dp[i] + dp[i-3]) % MOD
                if pressedKeys[i-1] in '79' and i >= 4 and pressedKeys[i-1] == pressedKeys[i-4]:
                    dp[i] = (dp[i] + dp[i-4]) % MOD
    return dp[n]

def minDistance(word1, word2):
    m, n = len(word1), len(word2)
    dp = list(range(n+1))
    for i in range(1, m+1):
        prev = dp[0]
        dp[0] = i
        for j in range(1, n+1):
            tmp = dp[j]
            if word1[i-1] == word2[j-1]:
                dp[j] = prev
            else:
                dp[j] = 1 + min(prev, dp[j], dp[j-1])
            prev = tmp
    return dp[n]

def longestCommonSubsequence(text1, text2):
    m, n = len(text1), len(text2)
    dp = [0] * (n+1)
    for i in range(1, m+1):
        prev = 0
        for j in range(1, n+1):
            tmp = dp[j]
            if text1[i-1] == text2[j-1]:
                dp[j] = prev + 1
            else:
                dp[j] = max(dp[j], dp[j-1])
            prev = tmp
    return dp[n]

def maxProfitK(k, prices):
    n = len(prices)
    if not prices or k == 0: return 0
    if k >= n // 2:
        return sum(max(0, prices[i+1]-prices[i]) for i in range(n-1))
    # buy[t] = max profit after buying with t transactions used
    # sell[t] = max profit after selling with t transactions completed
    buy = [-float("inf")] * (k+1)
    sell = [0] * (k+1)
    for p in prices:
        for t in range(k, 0, -1):
            sell[t] = max(sell[t], buy[t] + p)
            buy[t] = max(buy[t], sell[t-1] - p)
    return sell[k]

def maxCoins(nums):
    nums = [1] + nums + [1]
    n = len(nums)
    dp = [[0]*n for _ in range(n)]
    for length in range(2, n):
        for left in range(0, n-length):
            right = left + length
            for k in range(left+1, right):
                dp[left][right] = max(
                    dp[left][right],
                    nums[left]*nums[k]*nums[right] + dp[left][k] + dp[k][right]
                )
    return dp[0][n-1]

def isMatch(s, p):
    m, n = len(s), len(p)
    dp = [[False]*(n+1) for _ in range(m+1)]
    dp[0][0] = True
    for j in range(2, n+1):
        dp[0][j] = dp[0][j-2] and p[j-1] == '*'
    for i in range(1, m+1):
        for j in range(1, n+1):
            if p[j-1] == '*':
                dp[i][j] = dp[i][j-2]  # zero occurrences
                if p[j-2] == '.' or p[j-2] == s[i-1]:
                    dp[i][j] = dp[i][j] or dp[i-1][j]  # one or more
            elif p[j-1] == '.' or p[j-1] == s[i-1]:
                dp[i][j] = dp[i-1][j-1]
    return dp[m][n]

def isMatchWild(s, p):
    m, n = len(s), len(p)
    dp = [False] * (n+1)
    dp[0] = True
    for j in range(1, n+1):
        dp[j] = dp[j-1] and p[j-1] == '*'
    for i in range(1, m+1):
        new_dp = [False] * (n+1)
        for j in range(1, n+1):
            if p[j-1] == '*':
                new_dp[j] = dp[j] or new_dp[j-1]
            elif p[j-1] == '?' or p[j-1] == s[i-1]:
                new_dp[j] = dp[j-1]
        dp = new_dp
    return dp[n]

def numDistinct(s, t):
    m, n = len(s), len(t)
    dp = [0] * (n+1)
    dp[0] = 1
    for i in range(1, m+1):
        for j in range(min(i, n), 0, -1):
            if s[i-1] == t[j-1]:
                dp[j] += dp[j-1]
    return dp[n]

def change(amount, coins):
    dp = [0] * (amount + 1)
    dp[0] = 1
    for coin in coins:
        for a in range(coin, amount + 1):
            dp[a] += dp[a - coin]
    return dp[amount]

def numSquares(n):
    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    sq = 1
    while sq * sq <= n:
        for i in range(sq * sq, n + 1):
            dp[i] = min(dp[i], dp[i - sq * sq] + 1)
        sq += 1
    return dp[n]

def knapsack01(weights, values, W):
    dp = [0] * (W + 1)
    for w, v in zip(weights, values):
        for c in range(W, w - 1, -1):  # reverse!
            dp[c] = max(dp[c], dp[c - w] + v)
    return dp[W]

def rodCutting(prices, n):
    # prices[i] = revenue for rod of length i+1
    dp = [0] * (n + 1)
    for c in range(1, n + 1):
        for l in range(1, c + 1):
            dp[c] = max(dp[c], dp[c - l] + prices[l - 1])
    return dp[n]

def minCostPaint(costs):
    r, g, b = costs[0]
    for i in range(1, len(costs)):
        nr = costs[i][0] + min(g, b)
        ng = costs[i][1] + min(r, b)
        nb = costs[i][2] + min(r, g)
        r, g, b = nr, ng, nb
    return min(r, g, b)

def deleteAndEarn(nums):
    if not nums: return 0
    bucket = [0] * (max(nums) + 1)
    for n in nums:
        bucket[n] += n
    prev2, prev1 = 0, 0
    for val in bucket:
        prev2, prev1 = prev1, max(prev1, prev2 + val)
    return prev1

def maxNonAdj(arr):
    if not arr: return 0
    prev2, prev1 = 0, 0
    for x in arr:
        prev2, prev1 = prev1, max(prev1, prev2 + x)
    return prev1

def mincostTickets(days, costs):
    travel = set(days)
    dp = [0] * 366
    for i in range(1, 366):
        if i not in travel:
            dp[i] = dp[i-1]
        else:
            dp[i] = min(
                dp[i-1]             + costs[0],
                dp[max(0, i-7)]    + costs[1],
                dp[max(0, i-30)]   + costs[2]
            )
    return dp[365]

def findMaxForm(strs, m, n):
    dp = [[0]*(n+1) for _ in range(m+1)]
    for s in strs:
        zeros = s.count("0")
        ones  = s.count("1")
        for i in range(m, zeros-1, -1):
            for j in range(n, ones-1, -1):
                dp[i][j] = max(dp[i][j], dp[i-zeros][j-ones] + 1)
    return dp[m][n]

def longestCommonSubsequence(text1, text2):
    m, n = len(text1), len(text2)
    dp = [[0]*(n+1) for _ in range(m+1)]
    for i in range(1, m+1):
        for j in range(1, n+1):
            if text1[i-1] == text2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    return dp[m][n]

def integerBreak(n):
    dp = [0] * (n + 1)
    dp[1] = 1
    for i in range(2, n + 1):
        for j in range(1, i):
            dp[i] = max(dp[i], j*(i-j), j*dp[i-j])
    return dp[n]

def countBitsExtended(n):
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = dp[i >> 1] + (i & 1)
    positions = []
    for i in range(n + 1):
        bits = []
        tmp, pos = i, 0
        while tmp:
            if tmp & 1: bits.append(pos)
            tmp >>= 1
            pos += 1
        positions.append(bits)
    return dp, positions

counts, pos = countBitsExtended(5)

def maxAlternatingSum(nums):
    even, odd = 0, 0
    for n in nums:
        even, odd = max(even, odd + n), max(odd, even - n)
    return even

def maxConsecutiveAnswers(answerKey, k):
    def maxWindow(ch):
        left = count = res = 0
        for right in range(len(answerKey)):
            if answerKey[right] == ch: count += 1
            while count > k:
                if answerKey[left] == ch: count -= 1
                left += 1
            res = max(res, right - left + 1)
        return res
    return max(maxWindow("T"), maxWindow("F"))

def stoneGameDP(piles):
    n = len(piles)
    dp = [[0]*n for _ in range(n)]
    for i in range(n): dp[i][i] = piles[i]
    for length in range(2, n+1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = max(piles[i] - dp[i+1][j], piles[j] - dp[i][j-1])
    return dp[0][n-1] > 0

def numRollsToTarget(n, k, target):
    MOD = 10**9 + 7
    dp = [0] * (target + 1)
    dp[0] = 1
    for _ in range(n):
        ndp = [0] * (target + 1)
        for s in range(target + 1):
            if not dp[s]: continue
            for face in range(1, k + 1):
                if s + face <= target:
                    ndp[s + face] = (ndp[s + face] + dp[s]) % MOD
        dp = ndp
    return dp[target]

def knightDialer(n):
    MOD = 10**9 + 7
    moves = {
        0:[4,6], 1:[6,8], 2:[7,9], 3:[4,8],
        4:[0,3,9], 5:[], 6:[0,1,7],
        7:[2,6], 8:[1,3], 9:[2,4]
    }
    dp = [1] * 10
    for _ in range(n - 1):
        ndp = [0] * 10
        for key in range(10):
            for nxt in moves[key]:
                ndp[nxt] = (ndp[nxt] + dp[key]) % MOD
        dp = ndp
    return sum(dp) % MOD

def longestArithSeqLength(nums):
    dp = [{} for _ in nums]
    res = 2
    for i in range(1, len(nums)):
        for j in range(i):
            d = nums[i] - nums[j]
            dp[i][d] = dp[j].get(d, 1) + 1
            res = max(res, dp[i][d])
    return res

def longestPalindromeSubseq(s):
    n = len(s)
    dp = [[0]*n for _ in range(n)]
    for i in range(n): dp[i][i] = 1
    for length in range(2, n+1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = (dp[i+1][j-1] if length > 2 else 0) + 2
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])
    return dp[0][n-1]

def maxProfitCooldown(prices):
    hold = float("-inf")
    sold = rest = 0
    for p in prices:
        hold, sold, rest = max(hold, rest - p), hold + p, max(rest, sold)
    return max(sold, rest)

def numRollsToTargetFull(n, k, target):
    MOD = 10**9 + 7
    dp = [0] * (target + 1)
    dp[0] = 1
    for _ in range(n):
        ndp = [0] * (target + 1)
        for s in range(target + 1):
            if not dp[s]: continue
            for face in range(1, k + 1):
                ns = s + face
                if ns <= target:
                    ndp[ns] = (ndp[ns] + dp[s]) % MOD
        dp = ndp
    return dp[target]

def stoneGameIII(stoneValue):
    n = len(stoneValue)
    dp = [float("-inf")] * (n + 1)
    dp[n] = 0
    for i in range(n - 1, -1, -1):
        take = 0
        for k in range(1, 4):
            if i + k <= n:
                take += stoneValue[i + k - 1]
                dp[i] = max(dp[i], take - dp[i + k])
    if dp[0] > 0: return "Alice"
    if dp[0] < 0: return "Bob"
    return "Tie"

def maximumScore(nums, multipliers):
    n, m = len(nums), len(multipliers)
    dp = [[0]*(m+1) for _ in range(m+1)]
    for i in range(m-1, -1, -1):
        for left in range(i, -1, -1):
            right = n - 1 - (i - left)
            mul = multipliers[i]
            dp[i][left] = max(
                mul * nums[left]  + dp[i+1][left+1],
                mul * nums[right] + dp[i+1][left]
            )
    return dp[0][0]

def minSwap(nums1, nums2):
    keep, swap = 0, 1
    for i in range(1, len(nums1)):
        nkeep = nswap = float("inf")
        if nums1[i] > nums1[i-1] and nums2[i] > nums2[i-1]:
            nkeep = min(nkeep, keep)
            nswap = min(nswap, swap + 1)
        if nums1[i] > nums2[i-1] and nums2[i] > nums1[i-1]:
            nkeep = min(nkeep, swap)
            nswap = min(nswap, keep + 1)
        keep, swap = nkeep, nswap
    return min(keep, swap)

def findMaxFormFull(strs, m, n):
    dp = [[0]*(n+1) for _ in range(m+1)]
    for s in strs:
        z = s.count("0")
        o = s.count("1")
        for i in range(m, z-1, -1):
            for j in range(n, o-1, -1):
                dp[i][j] = max(dp[i][j], dp[i-z][j-o] + 1)
    return dp[m][n]

def deleteAndEarnFull(nums):
    if not nums: return 0
    max_val = max(nums)
    bucket = [0] * (max_val + 1)
    for n in nums:
        bucket[n] += n
    prev2 = prev1 = 0
    for v in bucket:
        prev2, prev1 = prev1, max(prev1, prev2 + v)
    return prev1

import bisect

def lengthOfLISFast(nums):
    tails = []
    for n in nums:
        pos = bisect.bisect_left(tails, n)
        if pos == len(tails):
            tails.append(n)
        else:
            tails[pos] = n
    return len(tails)

def strangePrinter(s):
    n = len(s)
    dp = [[0]*n for _ in range(n)]
    for i in range(n): dp[i][i] = 1
    for length in range(2, n+1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = dp[i][j-1] + 1
            for k in range(i, j):
                if s[k] == s[j]:
                    val = dp[i][k] + (dp[k+1][j-1] if k+1 <= j-1 else 0)
                    dp[i][j] = min(dp[i][j], val)
    return dp[0][n-1]

from functools import lru_cache

def removeBoxes(boxes):
    @lru_cache(maxsize=None)
    def dp(l, r, k):
        if l > r: return 0
        while l < r and boxes[l] == boxes[l+1]:
            l += 1; k += 1
        res = (k+1)**2 + dp(l+1, r, 0)
        for m in range(l+1, r+1):
            if boxes[m] == boxes[l]:
                res = max(res, dp(l+1, m-1, 0) + dp(m, r, k+1))
        return res
    return dp(0, len(boxes)-1, 0)

def mergeStones(stones, k):
    n = len(stones)
    if (n - 1) % (k - 1) != 0: return -1
    prefix = [0] * (n + 1)
    for i in range(n): prefix[i+1] = prefix[i] + stones[i]
    dp = [[0]*n for _ in range(n)]
    for length in range(k, n+1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = float("inf")
            for m in range(i, j, k-1):
                dp[i][j] = min(dp[i][j], dp[i][m] + dp[m+1][j])
            if (length - 1) % (k - 1) == 0:
                dp[i][j] += prefix[j+1] - prefix[i]
    return dp[0][n-1]

def cherryPickup2(grid):
    rows, cols = len(grid), len(grid[0])
    INF = float("-inf")
    dp = [[INF]*cols for _ in range(cols)]
    dp[0][cols-1] = grid[0][0] + (grid[0][cols-1] if cols > 1 else 0)
    for r in range(1, rows):
        ndp = [[INF]*cols for _ in range(cols)]
        for c1 in range(cols):
            for c2 in range(cols):
                if dp[c1][c2] == INF: continue
                for dc1 in [-1,0,1]:
                    for dc2 in [-1,0,1]:
                        nc1, nc2 = c1+dc1, c2+dc2
                        if 0 <= nc1 < cols and 0 <= nc2 < cols:
                            ch = grid[r][nc1] + (grid[r][nc2] if nc1!=nc2 else 0)
                            ndp[nc1][nc2] = max(ndp[nc1][nc2], dp[c1][c2] + ch)
        dp = ndp
    return max(dp[c1][c2] for c1 in range(cols) for c2 in range(cols) if dp[c1][c2] != INF)

def numMusicPlaylists(n, goal, k):
    MOD = 10**9 + 7
    dp = [[0]*(n+1) for _ in range(goal+1)]
    dp[0][0] = 1
    for i in range(1, goal+1):
        for j in range(1, n+1):
            dp[i][j] += dp[i-1][j-1] * (n - (j-1)) % MOD
            if j > k:
                dp[i][j] += dp[i-1][j] * (j - k) % MOD
            dp[i][j] %= MOD
    return dp[goal][n]

def lcsThree(s1, s2, s3):
    l1, l2, l3 = len(s1), len(s2), len(s3)
    dp = [[[0]*(l3+1) for _ in range(l2+1)] for _ in range(l1+1)]
    for i in range(1, l1+1):
        for j in range(1, l2+1):
            for k in range(1, l3+1):
                if s1[i-1] == s2[j-1] == s3[k-1]:
                    dp[i][j][k] = dp[i-1][j-1][k-1] + 1
                else:
                    dp[i][j][k] = max(dp[i-1][j][k], dp[i][j-1][k], dp[i][j][k-1])
    return dp[l1][l2][l3]
